css:
.tt-root{position:absolute;left:50%;bottom:64px;transform:translateX(-50%);display:flex;align-items:center;gap:var(--tt-gap);font-family:var(--tt-font);}
.tt-card{display:flex;align-items:center;gap:16px;background:linear-gradient(180deg,rgba(16,16,16,.95),rgba(12,12,12,.88));border:1px solid #2e2e2e;border-bottom:3px solid var(--tt-accent);border-radius:10px;padding:14px 34px 14px 16px;min-width:320px;box-shadow:0 6px 20px rgba(0,0,0,.35);}
.tt-avatar{width:var(--tt-avatar-size);height:var(--tt-avatar-size);overflow:hidden;background:#0d0d0d;border:1px solid rgba(255,255,255,.18);border-radius:50%;display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.tt-avatar img{width:100%;height:100%;object-fit:cover;display:none;}
.tt-avatar img.is-ready{display:block;}
.tt-fallback{color:#6a6a6a;font-size:30px;font-weight:700;}
.tt-avatar:has(img.is-ready) .tt-fallback{display:none;}
.tt-meta{display:flex;flex-direction:column;gap:4px;min-width:0;}
.tt-role{display:flex;align-items:center;gap:8px;font-size:var(--tt-role-size);font-weight:600;color:var(--tt-accent);letter-spacing:2.5px;line-height:1;}
.tt-role:before{content:'';width:14px;height:2px;background:var(--tt-accent);flex:0 0 auto;}
.tt-role:empty{display:none;}
.tt-name{font-size:var(--tt-name-size);font-weight:700;color:#f2f2f2;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
